$cs="Server=localhost\SQLEXPRESS;Database=GSDDashboard;Integrated Security=true;TrustServerCertificate=yes;"; $conn=New-Object System.Data.SqlClient.SqlConnection($cs); $conn.Open(); $cmd=$conn.CreateCommand(); $cmd.CommandText="SELECT DISTINCT YEAR(HolidayDate) AS Year, COUNT(*) AS Count FROM PublicHolidays GROUP BY YEAR(HolidayDate) ORDER BY Year"; $r=$cmd.ExecuteReader(); while($r.Read()){Write-Host $r[0] $r[1]}; $conn.Close()
